INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('bangsaen','หาดบางแสน','ทะเลและเกาะ','เมืองชลบุรี','ชายหาดที่อยู่คู่เมืองชลบุรีมานาน เป็นจุดพักผ่อนริมทะเลและพื้นที่ท่องเที่ยวสำคัญของชุมชนแสนสุข','เดินเล่นริมชายหาด ชมทะเล และรับประทานอาหารในย่านบางแสน','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','wave','ชายหาด ทะเล บางแสน เล่นน้ำ bangsaen beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('kohlarn','เกาะล้าน','ทะเลและเกาะ','บางละมุง','เกาะนอกชายฝั่งพัทยา มีชายหาดหลายแห่งและชุมชนท้องถิ่นที่รองรับการท่องเที่ยวทางทะเล','พักผ่อนริมชายหาด สำรวจเกาะ และชมทัศนียภาพทะเล','เกาะล้าน เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','island','เกาะ ทะเล ชายหาด ดำน้ำ เกาะล้าน koh larn island');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('sichang','เกาะสีชัง','วัฒนธรรม','เกาะสีชัง','เกาะที่มีความเกี่ยวข้องกับประวัติศาสตร์ราชสำนัก มีพระจุฑาธุชราชฐานและสะพานอัษฎางค์เป็นจุดน่าสนใจ','เรียนรู้ประวัติศาสตร์ เดินชมชุมชน และชมวิวชายฝั่ง','อำเภอเกาะสีชัง จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','island','เกาะ ทะเล ประวัติศาสตร์ ชุมชน สะพานอัษฎางค์ ko si chang island');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('nongnooch','สวนนงนุช','นันทนาการ','สัตหีบ','แหล่งท่องเที่ยวที่รวบรวมสวนจัดภูมิทัศน์และพื้นที่พักผ่อน เป็นหนึ่งในสถานที่ท่องเที่ยวที่ ททท. แนะนำในจังหวัดชลบุรี','ชมสวนและถ่ายภาพภูมิทัศน์หลากหลายรูปแบบ','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','garden','สวน สวนพฤกษศาสตร์ ธรรมชาติ ครอบครัว nong nooch garden');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('khaokheow','สวนสัตว์เปิดเขาเขียว','นันทนาการ','ศรีราชา','แหล่งเรียนรู้เกี่ยวกับสัตว์และธรรมชาติในพื้นที่อำเภอศรีราชา ซึ่งเป็นแหล่งท่องเที่ยวสำคัญของจังหวัด','เรียนรู้เรื่องสัตว์และการอนุรักษ์ เหมาะกับการท่องเที่ยวกับครอบครัว','ตำบลบางพระ อำเภอศรีราชา จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','garden','สวนสัตว์ สัตว์ ธรรมชาติ ครอบครัว เด็ก khao kheow zoo');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('ang-sila','ตลาดเก่าอ่างศิลา','ชุมชนและตลาด','เมืองชลบุรี','ย่านชุมชนเก่าริมทะเลที่สะท้อนวิถีชีวิตของคนอ่างศิลา และเป็นแหล่งท่องเที่ยวชุมชนที่ ททท. แนะนำ','เดินสำรวจชุมชน เลือกซื้อผลิตภัณฑ์ท้องถิ่น และสัมผัสบรรยากาศตลาด','ตำบลอ่างศิลา อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','town','ตลาด ชุมชน อ่างศิลา ของกิน อาหารทะเล ของฝาก ang sila market');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('sammuk','เขาสามมุข','ธรรมชาติ','เมืองชลบุรี','ภูเขาริมทะเลใกล้บางแสน มีศาลเจ้าแม่เขาสามมุขและทัศนียภาพชายฝั่ง เป็นจุดท่องเที่ยวที่รู้จักกันมานาน','ชมวิวชายฝั่งและแวะสักการะศาลเจ้าแม่เขาสามมุข','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','island','จุดชมวิว ภูเขา ธรรมชาติ ทะเล ศาลเจ้า khao sam muk viewpoint');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('nongmon','ตลาดหนองมน','ชุมชนและตลาด','เมืองชลบุรี','ตลาดของฝากที่เป็นที่รู้จักในจังหวัดชลบุรี มีอาหารและผลิตภัณฑ์ท้องถิ่นให้เลือกซื้อ','เลือกซื้อข้าวหลาม อาหาร และของฝากจากชุมชน','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','town','ตลาด ของกิน อาหาร ของฝาก ข้าวหลาม nong mon market');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('pattaya-beach','หาดพัทยา','ทะเลและเกาะ','บางละมุง','ชายหาดในเมืองพัทยาที่เชื่อมโยงกับย่านการท่องเที่ยวและกิจกรรมริมทะเล','เดินเลียบชายหาด ชมอ่าว และพักผ่อนในย่านพัทยา','เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','https://thai.tourismthailand.org/Attraction/หาดพัทยา','','wave','ชายหาด ทะเล พัทยากลาง pattaya beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('jomtien','หาดจอมเทียน','ทะเลและเกาะ','บางละมุง','ชายหาดทางตอนใต้ของเมืองพัทยา มีถนนเลียบชายฝั่งและย่านบริการนักท่องเที่ยว','เดินเล่นริมหาด พักผ่อน และเลือกกิจกรรมทางน้ำจากผู้ให้บริการ','หาดจอมเทียน เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','https://thai.tourismthailand.org/Attraction/หาดจอมเทียน','','wave','ชายหาด ทะเล จอมเทียน jomtien beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('bangsaray','หาดบางเสร่','ทะเลและเกาะ','สัตหีบ','ชายหาดในย่านบางเสร่ซึ่งมีความเชื่อมโยงกับวิถีชุมชนชายฝั่งสัตหีบ','พักผ่อนริมทะเลและสำรวจย่านชุมชนบางเสร่','ตำบลบางเสร่ อำเภอสัตหีบ จังหวัดชลบุรี','https://www.bangsaray.go.th/','','wave','ชายหาด ทะเล บางเสร่ bang saray beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('nangram','หาดนางรำ','ทะเลและเกาะ','สัตหีบ','ชายหาดในพื้นที่ดูแลของกองทัพเรือ ใกล้ท่าเรือจุกเสม็ด','ชมแนวหาดและพักผ่อนใต้ร่มไม้ ตรวจเงื่อนไขเข้าพื้นที่ก่อนเดินทาง','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Attraction/หาดนางรำ','','wave','ชายหาด ทะเล เล่นน้ำ nang ram beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('nangrong','หาดนางรอง','ทะเลและเกาะ','สัตหีบ','ชายหาดในเขตพื้นที่กองทัพเรือใกล้หาดนางรำ เป็นอีกจุดพักผ่อนของสัตหีบ','เดินชมแนวชายฝั่งและพักผ่อนตามเขตที่เจ้าหน้าที่อนุญาต','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Articles/nang-ram-beach-nang-rong-beach-nam-sai-beach-th','','wave','ชายหาด ทะเล เล่นน้ำ nang rong beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('namsai','หาดน้ำใส','ทะเลและเกาะ','สัตหีบ','ชายหาดที่อยู่ในพื้นที่ทหารเรือบริเวณแสมสาร มีระเบียบการเดินทางเข้าเยี่ยมชมเฉพาะ','ชมทะเลและพักผ่อน ตรวจสิทธิ์เข้าใช้พื้นที่และรถรับส่งกับหน่วยงานก่อนเดินทาง','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Articles/nang-ram-beach-nang-rong-beach-nam-sai-beach-th','','wave','ชายหาด ทะเล น้ำใส nam sai beach');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('samaesan','เกาะแสมสาร','ทะเลและเกาะ','สัตหีบ','เกาะในพื้นที่อนุรักษ์ของกองทัพเรือ ซึ่งเชื่อมโยงกับการเรียนรู้ทรัพยากรทางทะเล','สัมผัสธรรมชาติทางทะเลและกิจกรรมตามที่ผู้ดูแลอนุญาต ตรวจรอบเรือก่อนเดินทาง','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','wave','เกาะ ทะเล ดำน้ำ ชายหาด อนุรักษ์ samaesan island');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('kham','เกาะขาม สัตหีบ','ทะเลและเกาะ','สัตหีบ','เกาะในความดูแลของกองทัพเรือที่มีพื้นที่ชายหาดและทรัพยากรใต้ทะเล','เที่ยวเกาะแบบไปกลับ เรียนรู้การอนุรักษ์ และตรวจรอบเรือกับผู้ดูแล','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://thai.tourismthailand.org/Articles/ko-kham-th','','wave','เกาะ ทะเล ดำน้ำ ชายหาด koh kham island');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-yai','วัดใหญ่อินทาราม','วัดและศาสนสถาน','เมืองชลบุรี','วัดเก่าแก่ในตัวเมืองชลบุรี มีพระอุโบสถและงานจิตรกรรมที่สะท้อนศิลปกรรมของชุมชน','ไหว้พระและศึกษางานศิลปกรรม ตรวจวันเปิดอุโบสถก่อนเข้าชม','ตำบลบางปลาสร้อย อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://www.thailandtourismdirectory.go.th/attraction/4933','','wave','วัด ไหว้พระ ทำบุญ จิตรกรรม วัดใหญ่อินทราราม temple');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-saensuk','วัดแสนสุขสุทธิวราราม','วัดและศาสนสถาน','เมืองชลบุรี','วัดในย่านแสนสุขที่นำเสนอคติพุทธศาสนาผ่านประติมากรรมและพื้นที่เรียนรู้','ไหว้พระและศึกษาคติธรรมผ่านงานประติมากรรมภายในวัด','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://www.thailandtourismdirectory.go.th/th/attraction/3236','','wave','วัด ไหว้พระ ทำบุญ วัดแสนสุข temple');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-yan','วัดญาณสังวรารามวรมหาวิหาร','วัดและศาสนสถาน','บางละมุง','วัดในพระบรมราชูปถัมภ์ มีพื้นที่กว้างและศาสนสถานหลายรูปแบบ','ไหว้พระ ศึกษาสถาปัตยกรรม และเดินชมพื้นที่อย่างสงบ','ตำบลห้วยใหญ่ อำเภอบางละมุง จังหวัดชลบุรี','https://smartdastaapp.dasta.or.th/place/8','','wave','วัด ไหว้พระ ทำบุญ วัดญาณ wat yan temple');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-tabaek','วัดเขาตะแบก','วัดและศาสนสถาน','ศรีราชา','วัดในตำบลหนองขามที่มีเส้นทางขึ้นเขาและสกายวอล์กเป็นจุดเด่น','ไหว้พระและชมทิวทัศน์จากพื้นที่ทางเดินที่ทางวัดเปิดให้บริการ','ตำบลหนองขาม อำเภอศรีราชา จังหวัดชลบุรี','https://www.watkhaotabagsriracha.com/','','wave','วัด ไหว้พระ ทำบุญ สะพานกระจก สกายวอล์ก จุดชมวิว temple skywalk');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-sattahip','วัดสัตหีบ (วัดหลวงพ่ออี๋)','วัดและศาสนสถาน','สัตหีบ','วัดสำคัญของชุมชนสัตหีบที่เกี่ยวข้องกับหลวงพ่ออี๋และความศรัทธาของคนในพื้นที่','สักการะหลวงพ่ออี๋และเรียนรู้เรื่องราวของวัด','ตำบลสัตหีบ อำเภอสัตหีบ จังหวัดชลบุรี','https://www.thailandtourismdirectory.go.th/th/attraction/3244','','wave','วัด ไหว้พระ ทำบุญ หลวงพ่ออี๋ temple');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-chong','วัดช่องแสมสาร','วัดและศาสนสถาน','สัตหีบ','วัดที่มีวิหารหลวงพ่อดำเป็นศูนย์รวมศรัทธา และมองเห็นทิวทัศน์ย่านแสมสาร','ไหว้พระและชมทิวทัศน์ชุมชนชายฝั่งจากบริเวณวิหาร','ตำบลแสมสาร อำเภอสัตหีบ จังหวัดชลบุรี','https://www.thailandtourismdirectory.go.th/th/attraction/21395','','wave','วัด ไหว้พระ ทำบุญ หลวงพ่อดำ จุดชมวิว ทะเล temple sea view');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('wat-sam','วัดหลวงพี่แซม','วัดและศาสนสถาน','พนัสนิคม','วัดในอำเภอพนัสนิคมที่มีถ้ำจำลองและประติมากรรมเกี่ยวกับความเชื่อเป็นเอกลักษณ์','สักการะพระและชมพื้นที่ศิลปกรรมของวัด','อำเภอพนัสนิคม จังหวัดชลบุรี','https://www.tatmediaassets.com/file/10496146','','wave','วัด ไหว้พระ ทำบุญ ถ้ำ พญานาค temple');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('naja','ศาลเจ้าหน่าจาซาไท้จื้อ','วัดและศาสนสถาน','เมืองชลบุรี','ศาลเจ้าจีนในย่านอ่างศิลาที่มีงานสถาปัตยกรรมและเครื่องประดับตกแต่งแบบจีน','สักการะสิ่งศักดิ์สิทธิ์และชมงานศิลปกรรมจีนตามระเบียบของศาลเจ้า','ตำบลอ่างศิลา อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://thai.tourismthailand.org/Attraction/วิหารเทพสถิตพระกิติเฉลิม-ศาลเจ้าหน่าจาซาไท้จื้อ','','wave','ศาลเจ้า ไหว้พระ ทำบุญ นาจา จีน shrine');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('chichan','พระพุทธรูปแกะสลักเขาชีจรรย์','วัฒนธรรม','สัตหีบ','พื้นที่สำคัญของสัตหีบที่มีพระพุทธรูปบนหน้าผาหินเป็นจุดเด่น','สักการะพระพุทธรูปและชมภูมิทัศน์หน้าผา','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://www.dasta.or.th/th/article/229','','wave','ไหว้พระ พระพุทธรูป ภูเขา จุดชมวิว khao chi chan buddha mountain');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('sanctuary','ปราสาทสัจธรรม','วัฒนธรรม','บางละมุง','อาคารไม้ในย่านนาเกลือที่นำเสนอแนวคิดทางปรัชญาผ่านงานแกะสลัก','ศึกษาสถาปัตยกรรมไม้และงานศิลปกรรม ตรวจรอบเข้าชมกับผู้ให้บริการ','ตำบลนาเกลือ เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','https://sanctuaryoftruthmuseum.com/','','wave','พิพิธภัณฑ์ ไม้แกะสลัก สถาปัตยกรรม sanctuary of truth museum');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('bangphra','อ่างเก็บน้ำบางพระ','ธรรมชาติ','ศรีราชา','แหล่งน้ำสำคัญของศรีราชาที่มีพื้นที่ธรรมชาติและแหล่งอาศัยของนกบริเวณรอบอ่าง','ชมภูมิทัศน์และดูนกจากพื้นที่ที่เปิดให้เข้าถึงโดยไม่รบกวนสัตว์','ตำบลบางพระ อำเภอศรีราชา จังหวัดชลบุรี','https://www.thailandtourismdirectory.go.th/th/attraction/4938','','wave','อ่างเก็บน้ำ ธรรมชาติ ดูนก ออกกำลังกาย bang phra reservoir');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('kohloy','เกาะลอยศรีราชา','ธรรมชาติ','ศรีราชา','เกาะขนาดเล็กติดชายฝั่งศรีราชาที่มีสะพานเชื่อมกับฝั่งและพื้นที่พักผ่อน','เดินชมทะเล พักผ่อน และเยี่ยมชมวัดบนเกาะ','ตำบลศรีราชา อำเภอศรีราชา จังหวัดชลบุรี','https://thai.tourismthailand.org/Attraction/เกาะลอยศรีราชา','','wave','ทะเล สวนสาธารณะ วัด ไหว้พระ จุดชมวิว koh loy island park');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('pratamnak','จุดชมวิวเขาพระตำหนัก','ธรรมชาติ','บางละมุง','จุดชมทิวทัศน์บนเนินเขาของเมืองพัทยาที่มองเห็นแนวอ่าวและเมือง','ชมวิวอ่าวพัทยาและถ่ายภาพจากจุดที่เปิดให้เข้าชม','เมืองพัทยา อำเภอบางละมุง จังหวัดชลบุรี','https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/recommended-route-to-meet-greet-with-nong-moo-deng-phuket-chonburi-3-days-2-nights','','wave','จุดชมวิว เขา ทะเล อ่าว พัทยา pratamnak viewpoint');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('marine','สถาบันวิทยาศาสตร์ทางทะเล มหาวิทยาลัยบูรพา','พิพิธภัณฑ์และแหล่งเรียนรู้','เมืองชลบุรี','สถาบันของมหาวิทยาลัยบูรพาที่มีส่วนจัดแสดงเพื่อการเรียนรู้สิ่งมีชีวิตและระบบนิเวศทางทะเล','ชมสัตว์น้ำและนิทรรศการวิทยาศาสตร์ เหมาะกับการเรียนรู้นอกห้องเรียน','ตำบลแสนสุข อำเภอเมืองชลบุรี จังหวัดชลบุรี','https://site.bims.buu.ac.th/b/','','wave','พิพิธภัณฑ์ อควาเรียม สัตว์น้ำ แมงกะพรุน บางแสน ครอบครัว เด็ก aquarium museum');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('ramayana','สวนน้ำรามายณะ','นันทนาการ','สัตหีบ','สวนน้ำในย่านนาจอมเทียน มีพื้นที่เครื่องเล่นและสระสำหรับการพักผ่อน','เลือกกิจกรรมทางน้ำตามข้อกำหนดอายุ ส่วนสูง และความปลอดภัย','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://www.ramayanawaterpark.com/','','wave','สวนน้ำ สวนสนุก ครอบครัว เด็ก ramayana water park');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('aquaverse','Columbia Pictures Aquaverse','นันทนาการ','สัตหีบ','แหล่งนันทนาการในบางเสร่ที่เชื่อมโยงธีมภาพยนตร์กับกิจกรรมสวนน้ำ','สนุกกับเครื่องเล่นตามข้อกำหนดของผู้ให้บริการ','ตำบลบางเสร่ อำเภอสัตหีบ จังหวัดชลบุรี','https://columbiapicturesaquaverse.com/en/','','wave','โคลัมเบีย อควาเวิร์ส สวนน้ำ สวนสนุก ครอบครัว water park aquaverse');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('millionstone','อุทยานหินล้านปีและฟาร์มจระเข้พัทยา','นันทนาการ','บางละมุง','แหล่งท่องเที่ยวที่รวบรวมสวนหินและพื้นที่จัดแสดงสัตว์ในอำเภอบางละมุง','ชมการจัดสวนหินและเรียนรู้เกี่ยวกับสัตว์ตามเส้นทางที่จัดไว้','ตำบลหนองปลาไหล อำเภอบางละมุง จังหวัดชลบุรี','https://www.thaistonepark.org/','','wave','สวนหิน จระเข้ สวนสัตว์ ครอบครัว million years stone park crocodile');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('minisiam','เมืองจำลอง พัทยา','พิพิธภัณฑ์และแหล่งเรียนรู้','บางละมุง','แหล่งท่องเที่ยวที่นำเสนอสถานที่สำคัญผ่านสถาปัตยกรรมจำลอง','ชมแบบจำลองและเรียนรู้รูปแบบสถาปัตยกรรมจากหลายพื้นที่','ตำบลนาเกลือ อำเภอบางละมุง จังหวัดชลบุรี','https://thai.tourismthailand.org/Destinations/Provinces/chon-buri/464','','wave','เมืองจำลอง พิพิธภัณฑ์ สถาปัตยกรรม ครอบครัว mini siam museum');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('floatingmarket','ตลาดน้ำ 4 ภาค พัทยา','ชุมชนและตลาด','บางละมุง','แหล่งท่องเที่ยวที่นำเสนออาหาร สินค้า และบรรยากาศตลาดในธีมภูมิภาคของไทย','เดินชมตลาด เลือกอาหารและสินค้าตามความสนใจ','ตำบลหนองปรือ อำเภอบางละมุง จังหวัดชลบุรี','https://www.dasta.or.th/th/article/5179','','wave','ตลาด ตลาดน้ำ อาหาร ของกิน ของฝาก floating market');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('chakngeaw','ตลาดจีนโบราณบ้านชากแง้ว','ชุมชนและตลาด','บางละมุง','ชุมชนไทยเชื้อสายจีนที่สืบทอดเรื่องราว วิถีชีวิต และอาหารท้องถิ่น','เดินชมชุมชนและเลือกชิมอาหาร ตรวจวันที่จัดตลาดก่อนเดินทาง','ตำบลห้วยใหญ่ อำเภอบางละมุง จังหวัดชลบุรี','https://www.dasta.or.th/th/article/352','','wave','ตลาด ชุมชน จีน อาหาร ของกิน ถนนคนเดิน chak ngaeo market');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('tutu','Tutu Beach','คาเฟ่','สัตหีบ','คาเฟ่ริมชายหาดย่านนาจอมเทียนที่ใช้โทนสีชมพูเป็นเอกลักษณ์','พักดื่มเครื่องดื่มและชมวิวชายฝั่ง ตรวจเงื่อนไขการใช้พื้นที่กับร้าน','ซอยนาจอมเทียน 10 ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://www.thailandtravel.or.jp/tutu-beach/','','wave','คาเฟ่ ร้านกาแฟ กาแฟ ขนม ถ่ายรูป ทะเล ริมทะเล ชายหาด ตูตู บีช tutu beach cafe coffee');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('cave','Cave Beach Club','คาเฟ่','สัตหีบ','ร้านอาหารและคาเฟ่ริมทะเลในย่านนาจอมเทียนที่เน้นพื้นที่พักผ่อน','นั่งพัก รับประทานอาหารหรือเครื่องดื่ม และชมบรรยากาศชายฝั่ง','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://www.facebook.com/CaveBeachClub/','','wave','คาเฟ่ ร้านกาแฟ กาแฟ ร้านอาหาร ถ่ายรูป ทะเล ริมทะเล ชายหาด เคฟ บีช cafe coffee');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('papa','Papa Beach Pattaya','คาเฟ่','สัตหีบ','คาเฟ่และร้านอาหารริมทะเลย่านนาจอมเทียน เป็นจุดแวะพักของผู้เดินทางในพื้นที่','ดื่มเครื่องดื่ม ชมวิว และถ่ายภาพในบริเวณที่ร้านอนุญาต','ตำบลนาจอมเทียน อำเภอสัตหีบ จังหวัดชลบุรี','https://www.ktc.co.th/article/travel-stories/thailand/th/recommended-places-to-take-photos-in-pattaya','','wave','คาเฟ่ ร้านกาแฟ กาแฟ ร้านอาหาร ถ่ายรูป ทะเล ริมทะเล ชายหาด ปาป้า บีช cafe coffee');
INSERT INTO places (id,name,category,district,history,highlight,address,source,image,art,keywords) VALUES ('coffeewar','Coffee War 331 Station','คาเฟ่','สัตหีบ','คาเฟ่ในย่านถนน 331 ที่นำเครื่องบินมาประยุกต์เป็นพื้นที่บริการเครื่องดื่ม','สัมผัสบรรยากาศคาเฟ่ธีมเครื่องบินและถ่ายภาพตามพื้นที่ให้บริการ','ตำบลพลูตาหลวง อำเภอสัตหีบ จังหวัดชลบุรี','https://www.wongnai.com/restaurants/584383hf-coffee-war-331-station-ถนน-331','','wave','คาเฟ่ ร้านกาแฟ กาแฟ เครื่องบิน ขนม ถ่ายรูป คอฟฟี่วอร์ cafe coffee airplane');
