CREATE DATABASE IF NOT EXISTS chonburi_travel CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE chonburi_travel;
CREATE TABLE IF NOT EXISTS places (id VARCHAR(64) PRIMARY KEY,name VARCHAR(200) NOT NULL,category VARCHAR(100) NOT NULL,district VARCHAR(100) NOT NULL,history TEXT NOT NULL,highlight TEXT NOT NULL,address VARCHAR(500) NOT NULL,source VARCHAR(2000) NOT NULL,image VARCHAR(2000) NOT NULL DEFAULT '',keywords TEXT,art VARCHAR(20) NOT NULL DEFAULT 'wave');
